-- إلى جدول guidance_documents (المُنشأ فى 008). طلب المستخدم تحميل الدليل من جهازه ووضعه فى
-- الأدلة الاسترشادية على المنصة — نفس الطلب ونفس المنهجية المتبعة سابقاً فى 009 (دليل حماية
-- المتعاملين). الملف حُمِّل يدوياً من جهاز المستخدم (نفس حجم البايت 31,635,950 المطابق تماماً
-- للنسخة الرسمية على fra.gov.eg/wp-content/uploads/2025/11/Final2 (1).pdf، تحقّق عبر HEAD
-- request مباشر)، واستُخرج نصه محلياً بمكتبة pdfplumber (لا OCR، أصل الملف مُصدَّر من Word)، مع
-- تصحيح مشكلة انعكاس اتجاه الأسطر العربية المعروفة فى استخراج pdfplumber لنصوص RTL — راجع
-- quality_note أدناه للتفاصيل الكاملة وحدود الاستخراج.
-- قابل لإعادة التشغيل بأمان (idempotent) عبر ON CONFLICT (official_url) DO NOTHING، بنفس نمط 009.

